// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        // Fee is set to 0 in setUp, so unclaimedFees for the token that will be
        // transferred is exactly 0.  withdrawFees with fee == 0 would make both
        // versions identical (nothing to withdraw, nothing to leak).  Set a
        // non-zero fee through the owner-only setter and accrue a fee into
        // unclaimedFees[address(this)] via a fillOrder of a SHORT order.
        c.setFee(1);

        // The only way to populate unclaimedFees for an ERC20 token is to run
        // fillOrder, which requires a valid EIP-712 signature from the maker.
        // Build a minimal short call order so the fee accrues to address(this)
        // (the contract itself is the baseAsset here -- see below).
        //
        // Simpler: since fee == 0 initially and setFee only changes fee, the
        // reference contract still holds unclaimedFees(k) == 0 for every key it
        // ever saw only if no fee was ever accrued.  To exercise the bug we
        // must accrue a fee.  We achieve that by making a fillOrder on a short
        // order whose baseAsset is an ERC20 we deploy and whose premium is
        // non-zero.
        //
        // However, withdrawFees transfers via ERC20(asset).transfer, which
        // requires the contract to hold that asset.  The fillOrder flow sends
        // the fee amount to address(this), so the contract does hold it.
        //
        // We keep the fuzz surface small: fuzz only the recipient; accrual is
        // deterministic.
        //
        // To keep the scenario wide and simple, we instead assert the rule on
        // an asset whose unclaimedFees starts at 0: after calling withdrawFees
        // the reference leaves it at 0, the bug leaves it unchanged (also 0 if
        // it started at 0).  That would not distinguish them.  So we must
        // accrue first.

        // Accrual via fillOrder needs a valid signature.  Use vm.sign.
        uint256 makerKey = 0xBEEF;
        address maker = vm.addr(makerKey);

        // Deploy a minimal ERC20 that supports transfer/transferFrom/approve.
        MockERC20 token = new MockERC20();
        token.mint(maker, 1e18);

        PuttyV2.Order memory order;
        order.maker = maker;
        order.isCall = false;
        order.isLong = false;
        order.baseAsset = address(token);
        order.strike = 1;
        order.premium = 1000;
        order.duration = 1 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = 0;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        // Short put order: maker deposits strike, filler receives strike,
        // premium flows from filler to maker, fee accrues to address(this).
        vm.prank(maker);
        token.approve(address(c), type(uint256).max);

        vm.prank(address(this));
        token.mint(address(this), 10_000);
        token.approve(address(c), type(uint256).max);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 accrued = c.unclaimedFees(address(token));
        require(accrued > 0, "setup failed to accrue fee");

        c.withdrawFees(address(token), recipient);

        uint256 afterWithdraw = c.unclaimedFees(address(token));
        assertTrue(afterWithdraw == 0, "unclaimedFees must be zeroed after withdrawal");
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
